const grafanaHost = 'GRAFANA_HOST';

// Pairs each Prometheus answer with the check that asked it, by position.
const checks = $('Build checks').all().map((item) => item.json);
const answers = $input.all();

const problems = [];   // one row per offending object
const summary = [];    // one row per check
const findings = [];    // short lines for the subject, the event and the text part

for (let index = 0; index < checks.length; index++) {
  const check = checks[index];
  const body = answers[index]?.json;
  const series = body?.data?.result;

  if (!Array.isArray(series)) {
    summary.push({ name: check.name, result: 'no data', isFinding: true });
    findings.push(check.name + ': no data');
    continue;
  }

  if (check.kind === 'objects') {
    if (series.length === 0) {
      summary.push({ name: check.name, result: 'none', isFinding: false });
      continue;
    }
    for (const entry of series) {
      const object = (check.labels ?? [])
        .map((label) => entry.metric[label])
        .filter(Boolean)
        .join('/');
      const rounded = Math.round(Number(entry.value[1]) * 10) / 10;
      const detail = check.detailLabel
        ? (entry.metric[check.detailLabel] ?? '')
        : check.detailSuffix
          ? rounded + check.detailSuffix
          : '';
      problems.push({ object: object || '(unlabelled)', issue: check.name, detail });
      findings.push(check.name + ': ' + (object || '(unlabelled)') + (detail ? ' (' + detail + ')' : ''));
    }
    summary.push({ name: check.name, result: String(series.length), isFinding: true });
    continue;
  }

  if (series.length === 0) {
    summary.push({ name: check.name, result: 'no data', isFinding: true });
    findings.push(check.name + ': no data');
    continue;
  }
  const value = Number(series[0].value[1]);
  const reading = value + (check.unit ?? '');
  const isFinding =
    (check.warnAbove !== undefined && value > check.warnAbove) ||
    (check.warnBelow !== undefined && value < check.warnBelow);
  if (isFinding) findings.push(check.name + ': ' + reading);
  summary.push({ name: check.name, result: reading, isFinding });
}

const subject = problems.length || findings.length
  ? 'Cluster digest \u2014 ' + findings.length + (findings.length === 1 ? ' finding' : ' findings')
  : 'Cluster digest \u2014 all clear';
const grafanaUrl = 'http://' + grafanaHost + '/';

function escapeHtml(text) {
  const replacements = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(text).replace(/[&<>"']/g, (character) => replacements[character]);
}

// Inline styles only: mail clients strip stylesheets.
const tableStyle = 'border-collapse:collapse;font:14px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif';
const headStyle = 'text-align:left;padding:6px 10px;border-bottom:2px solid #d0d0d0;font-weight:600';
const cellStyle = 'padding:6px 10px;border-bottom:1px solid #ececec;vertical-align:top';
const warnStyle = cellStyle + ';background:#fff6e5';
const monoStyle = cellStyle + ';font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px';

const problemTable = problems.length
  ? '<p style="margin:0 0 6px;font-weight:600">What is wrong</p><table style="' + tableStyle + '"><thead><tr>' +
    '<th style="' + headStyle + '">Object</th><th style="' + headStyle + '">Issue</th>' +
    '<th style="' + headStyle + '">Detail</th></tr></thead><tbody>' +
    problems.map((row) =>
      '<tr><td style="' + monoStyle + ';background:#fff6e5">' + escapeHtml(row.object) + '</td>' +
      '<td style="' + warnStyle + '">' + escapeHtml(row.issue) + '</td>' +
      '<td style="' + warnStyle + '">' + escapeHtml(row.detail) + '</td></tr>').join('') +
    '</tbody></table>'
  : '<p style="margin:0 0 6px">No pod, deployment, StatefulSet, DaemonSet, Job, PVC or node is reporting a problem.</p>';

const summaryTable = '<p style="margin:16px 0 6px;font-weight:600">Every check</p><table style="' + tableStyle + '"><thead><tr>' +
  '<th style="' + headStyle + '">Check</th><th style="' + headStyle + ';text-align:right">Result</th>' +
  '</tr></thead><tbody>' +
  summary.map((row) => {
    const style = row.isFinding ? warnStyle : cellStyle;
    return '<tr><td style="' + style + '">' + escapeHtml(row.name) + '</td>' +
           '<td style="' + style + ';text-align:right;white-space:nowrap">' + escapeHtml(row.result) + '</td></tr>';
  }).join('') + '</tbody></table>';

const html = '<div style="font:14px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#222">' +
  problemTable + summaryTable +
  '<p style="margin:14px 0 0;font-size:13px"><a href="' + grafanaUrl + '">Dashboards and alert history</a></p></div>';

// Plain-text fallback, for clients that drop the HTML part.
const content = [
  problems.length ? 'What is wrong:' : 'Nothing is reporting a problem.',
  ...problems.map((row) => '  ' + row.object + ' \u2014 ' + row.issue + (row.detail ? ' (' + row.detail + ')' : '')),
  '',
  'Every check:',
  ...summary.map((row) => (row.isFinding ? '  ! ' : '    ') + row.name + ': ' + row.result),
  '',
  'Dashboards and alert history: ' + grafanaUrl,
].join('\n');

return [{ json: { subject, content, html, findings, findingCount: findings.length, problems } }];

// A node that returns no items stops its branch, so an all-clear run books nothing.
const digest = $input.first().json;
if (!digest.findingCount) return [];

const eventSummary =
  'Check cluster health \u2014 ' + digest.findingCount + (digest.findingCount === 1 ? ' finding' : ' findings');

const eventDescription = [
  "The daily digest could not clear these:",
  ...digest.findings.map((finding) => '\u2022 ' + finding),
  '',
  'Dashboards and alert history: http://GRAFANA_HOST/',
].join('\n');

return [{ json: { eventSummary, eventDescription } }];
